window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9b095ccb7958c21c"]={"versions": [{"id": "FIG-9b095ccb7958c21c", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene des AUTOSAR-Metamodells) zur Veranschaulichung von Modelländerungen und Modell-Interoperabilität (Change-Propagation bei modifizierten Attributwerten). Das Diagramm stellt eine AUTOSAR-Paketstruktur mit Schnittstellen- und Datentypdefinitionen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind folgende M1-Instanzen (Objekte) mit Attributen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>:ARPackage</code> mit Attribut <code>shortName = OEM</code>. Es aggregiert über Kompositionsbeziehungen (<code>+element</code>) das Interface <code>:SenderReceiverInterface</code> sowie den Datentyp <code>:ApplicationPrimitiveDataType</code>.\n</li><li><code>:SenderReceiverInterface</code> mit Attributen <code>isService = false</code> und <code>shortName = interface</code>. Es aggregiert per Komposition (<code>+dataElement</code>) ein <code>:VariableDataPrototype</code>.\n</li><li><code>:VariableDataPrototype</code> mit Attribut <code>shortName = velocity</code>. Es referenziert über eine gerichtete Assoziation (<code>+type</code>) das Datentyp-Objekt <code>:ApplicationPrimitiveDataType</code>.\n</li><li><code>:ApplicationPrimitiveDataType</code> mit Attribut <code>shortName = velocityType</code>. Es aggregiert über Kompositionen:\n<ul class=\"fig-list\"><li><code>:DisplayFormatString</code> mit Attribut <code>value = %f6.2</code> über die Rolle <code>+displayFormat</code>.\n</li><li><code>:NumericalValueSpecification</code> mit den Attributen <code>VALUE = 20000</code> und <code>value = 20000</code> über die Rolle <code>+invalidValue</code>.\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Die Instanzen <code>:ApplicationPrimitiveDataType</code> und <code>:NumericalValueSpecification</code> sind zur Kennzeichnung der Modellmodifikation farblich hervorgehoben (grün unterlegt).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne Verhaltens- oder Sequenzsemantik. Dargestellt ist der Zustand nach einer Modellmodifikation, bei der der ungültige Wert (<code>invalidValue</code>) des Anwendungstyps auf die Spezifikation <code>20000</code> geändert wurde. Die Änderung pflanzt sich hierarchisch vom Kind-Objekt auf den Datentyp fort.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanz für AUTOSAR-Autorentools und Austauschformate gemäß AUTOSAR TR Interoperability of Autosar Tools. Das Diagramm illustriert, wie Änderungen an zusammengesetzten oder aggregierten Modellelementen (hier <code>invalidValue</code> als <code>NumericalValueSpecification</code>) auf das enthaltende identifizierbare Element (<code>ApplicationPrimitiveDataType</code>) und weiter auf Paketebene (<code>ARPackage</code>) propagiert bzw. versioniert werden müssen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9d69781c49571ade", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene des AUTOSAR-Metamodells) zur Veranschaulichung von Modelländerungen und Modell-Interoperabilität (Change-Propagation bei modifizierten Attributwerten). Das Diagramm stellt eine AUTOSAR-Paketstruktur mit Schnittstellen- und Datentypdefinitionen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind folgende M1-Instanzen (Objekte) mit Attributen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>:ARPackage</code> mit Attribut <code>shortName = OEM</code>. Es aggregiert über Kompositionsbeziehungen (<code>+element</code>) das Interface <code>:SenderReceiverInterface</code> sowie den Datentyp <code>:ApplicationPrimitiveDataType</code>.\n</li><li><code>:SenderReceiverInterface</code> mit Attributen <code>isService = false</code> und <code>shortName = interface</code>. Es aggregiert per Komposition (<code>+dataElement</code>) ein <code>:VariableDataPrototype</code>.\n</li><li><code>:VariableDataPrototype</code> mit Attribut <code>shortName = velocity</code>. Es referenziert über eine gerichtete Assoziation (<code>+type</code>) das Datentyp-Objekt <code>:ApplicationPrimitiveDataType</code>.\n</li><li><code>:ApplicationPrimitiveDataType</code> mit Attribut <code>shortName = velocityType</code>. Es aggregiert über Kompositionen:\n<ul class=\"fig-list\"><li><code>:DisplayFormatString</code> mit Attribut <code>value = %f6.2</code> über die Rolle <code>+displayFormat</code>.\n</li><li><code>:NumericalValueSpecification</code> mit den Attributen <code>VALUE = 20000</code> und <code>value = 20000</code> über die Rolle <code>+invalidValue</code>.\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Die Instanzen <code>:ApplicationPrimitiveDataType</code> und <code>:NumericalValueSpecification</code> sind zur Kennzeichnung der Modellmodifikation farblich hervorgehoben (grün unterlegt).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne Verhaltens- oder Sequenzsemantik. Dargestellt ist der Zustand nach einer Modellmodifikation, bei der der ungültige Wert (<code>invalidValue</code>) des Anwendungstyps auf die Spezifikation <code>20000</code> geändert wurde. Die Änderung pflanzt sich hierarchisch vom Kind-Objekt auf den Datentyp fort.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanz für AUTOSAR-Autorentools und Austauschformate gemäß AUTOSAR TR Interoperability of Autosar Tools. Das Diagramm illustriert, wie Änderungen an zusammengesetzten oder aggregierten Modellelementen (hier <code>invalidValue</code> als <code>NumericalValueSpecification</code>) auf das enthaltende identifizierbare Element (<code>ApplicationPrimitiveDataType</code>) und weiter auf Paketebene (<code>ARPackage</code>) propagiert bzw. versioniert werden müssen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9b095ccb7958c21c", "to": "FIG-9d69781c49571ade", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
